     1→/**
     2→ * P1-A 知识库管理面板（借鉴 DB-GPT RAG 知识库）。
     3→ * 管理员为当前数据源登记业务知识（指标口径、术语表、计算规则），
     4→ * 问数时服务端检索相关片段注入 prompt，弥补 Schema 元数据表达不足。
     5→ * 支持查看文档详情（切块明细）与编辑维护（重新切块 + embedding）。
     6→ */
     7→import React, { useCallback, useEffect, useState } from 'react';
     8→import { BookOpen, Plus, Trash2, RefreshCw, X, Lightbulb, Eye, Pencil } from 'lucide-react';
     9→import { apiFetch } from '../../api/client';
    10→import { useAuthStore } from '../../hooks/useAuthStore';
    11→import { DataSource } from '../../types/analytics';
    12→
    13→interface KnowledgeDoc {
    14→  docId: string;
    15→  title: string;
    16→  chunkCount: number;
    17→  createdBy: string;
    18→  createdAt: string;
    19→}
    20→
    21→interface KnowledgeDocDetail {
    22→  docId: string;
    23→  dataSourceId: string;
    24→  title: string;
    25→  createdBy: string;
    26→  createdAt: string;
    27→  chunkCount: number;
    28→  chunks: { index: number; text: string }[];
    29→}
    30→
    31→export const KnowledgeBasePanel: React.FC<{ dataSources: DataSource[]; initialId?: string }> = ({
    32→  dataSources,
    33→  initialId,
    34→}) => {
    35→  const isAdmin = useAuthStore((s) => s.user?.role === 'ADMIN');
    36→  const [selectedId, setSelectedId] = useState(initialId || dataSources[0]?.id || '');
    37→  const [docs, setDocs] = useState<KnowledgeDoc[]>([]);
    38→  const [loading, setLoading] = useState(false);
    39→  const [showAdd, setShowAdd] = useState(false);
    40→  const [title, setTitle] = useState('');
    41→  const [content, setContent] = useState('');
    42→  const [saving, setSaving] = useState(false);
    43→  const [error, setError] = useState<string | null>(null);
    44→  const [notice, setNotice] = useState<string | null>(null);
    45→  // 维护态：editingDoc 非空表示编辑现有文档（表单复用新增表单）
    46→  const [editingDoc, setEditingDoc] = useState<KnowledgeDoc | null>(null);
    47→  // 详情弹窗
    48→  const [detail, setDetail] = useState<KnowledgeDocDetail | null>(null);
    49→  const [detailLoading, setDetailLoading] = useState(false);
    50→
    51→  const selectedDs = dataSources.find((d) => d.id === selectedId);
    52→
    53→  const loadDocs = useCallback(async () => {
    54→    if (!selectedId) return;
    55→    setLoading(true);
    56→    setError(null);
    57→    try {
    58→      const res = await apiFetch(`/api/knowledge?dataSourceId=${encodeURIComponent(selectedId)}`);
    59→      const data = await res.json();
    60→      if (!res.ok) throw new Error(data.error || '加载知识库失败');
    61→      setDocs(data.docs || []);
    62→    } catch (err: any) {
    63→      setError(err.message || '加载知识库失败');
    64→    } finally {
    65→      setLoading(false);
    66→    }
    67→  }, [selectedId]);
    68→
    69→  useEffect(() => {
    70→    loadDocs();
    71→  }, [loadDocs]);
    72→
    73→  useEffect(() => {
    74→    if (!notice) return;
    75→    const t = setTimeout(() => setNotice(null), 4000);
    76→    return () => clearTimeout(t);
    77→  }, [notice]);
    78→
    79→  const closeForm = () => {
    80→    setShowAdd(false);
    81→    setEditingDoc(null);
    82→    setTitle('');
    83→    setContent('');
    84→  };
    85→
    86→  const handleSubmit = async () => {
    87→    if (!title.trim() || !content.trim() || saving) return;
    88→    setSaving(true);
    89→    setError(null);
    90→    try {
    91→      const isEdit = !!editingDoc;
    92→      const res = await apiFetch(isEdit ? `/api/knowledge/${encodeURIComponent(editingDoc!.docId)}` : '/api/knowledge', {
    93→        method: isEdit ? 'PUT' : 'POST',
    94→        headers: { 'Content-Type': 'application/json' },
    95→        body: JSON.stringify(isEdit ? { title: title.trim(), content } : { dataSourceId: selectedId, title: title.trim(), content }),
    96→      });
    97→      const data = await res.json();
    98→      if (!res.ok) throw new Error(data.error || (isEdit ? '保存失败' : '登记失败'));
    99→      closeForm();
   100→      setNotice(`知识「${title.trim()}」已${isEdit ? '更新' : '登记'}（切分为 ${data.chunkCount} 个片段）。`);
   101→      loadDocs();
   102→    } catch (err: any) {
   103→      setError(err.message || '保存失败');
   104→    } finally {
   105→      setSaving(false);
   106→    }
   107→  };
   108→
   109→  const handleEdit = async (doc: KnowledgeDoc) => {
   110→    // 拉取完整内容（拼接切块）回填编辑表单
   111→    setError(null);
   112→    try {
   113→      const res = await apiFetch(`/api/knowledge/${encodeURIComponent(doc.docId)}`);
   114→      const data = await res.json();
   115→      if (!res.ok) throw new Error(data.error || '加载详情失败');
   116→      const d = data.doc as KnowledgeDocDetail;
   117→      setEditingDoc(doc);
   118→      setTitle(d.title);
   119→      setContent(d.chunks.map((c) => c.text).join('\n'));
   120→      setShowAdd(true);
   121→      setDetail(null);
   122→    } catch (err: any) {
   123→      setError(err.message || '加载详情失败');
   124→    }
   125→  };
   126→
   127→  const handleView = async (doc: KnowledgeDoc) => {
   128→    setError(null);
   129→    setDetailLoading(true);
   130→    setDetail({ docId: doc.docId, dataSourceId: selectedId, title: doc.title, createdBy: doc.createdBy, createdAt: doc.createdAt, chunkCount: doc.chunkCount, chunks: [] });
   131→    try {
   132→      const res = await apiFetch(`/api/knowledge/${encodeURIComponent(doc.docId)}`);
   133→      const data = await res.json();
   134→      if (!res.ok) throw new Error(data.error || '加载详情失败');
   135→      setDetail(data.doc);
   136→    } catch (err: any) {
   137→      setDetail(null);
   138→      setError(err.message || '加载详情失败');
   139→    } finally {
   140→      setDetailLoading(false);
   141→    }
   142→  };
   143→
   144→  const handleDelete = async (doc: KnowledgeDoc) => {
   145→    if (!window.confirm(`确认删除知识「${doc.title}」？`)) return;
   146→    try {
   147→      const res = await apiFetch(`/api/knowledge/${encodeURIComponent(doc.docId)}`, { method: 'DELETE' });
   148→      const data = await res.json();
   149→      if (!res.ok) throw new Error(data.error || '删除失败');
   150→      setNotice(`知识「${doc.title}」已删除。`);

